--Who is the subject of the contact?
UPDATE progressnote
SET focusperson = jsonb_set(
    focusperson::jsonb, 
    '{focuspersonjson}', 
    (
        SELECT jsonb_agg(
            CASE 
                WHEN elem->>'intakeservicerequestactorid' = '9e735f6d-2bff-4813-a3a5-6eb7088eeba5'
                     OR elem->>'intakeservicerequestactorid' = '2f641a35-ec16-4a6b-87b9-55b028824109'
                THEN jsonb_set(
                        jsonb_set(
                            jsonb_set(
                                elem, 
                                '{intakeservicerequestactorid}', 
                                '"ec94c2e8-84ec-455a-b690-5403cd80cb8c"', 
                                false
                            ),
                            '{participantid}', 
                            '"ec94c2e8-84ec-455a-b690-5403cd80cb8c"', 
                            false
                        ),
                        '{lastname}', 
                        '"Hudson"', 
                        false
                    )
                ELSE elem
            END
        )
        FROM jsonb_array_elements(focusperson::jsonb->'focuspersonjson') AS elem
    )
),
updatedby = 'CJAMS-60331',
updatedon = now()
WHERE servicecaseid = '106d52af-2455-478f-b3fb-97e6f8e94b7d'
  AND activeflag = 1
  AND (
      focusperson::jsonb->'focuspersonjson' @> '[{"intakeservicerequestactorid": "9e735f6d-2bff-4813-a3a5-6eb7088eeba5"}]'::jsonb
      OR focusperson::jsonb->'focuspersonjson' @> '[{"intakeservicerequestactorid": "2f641a35-ec16-4a6b-87b9-55b028824109"}]'::jsonb
  );

