UPDATE assessment
SET submissiondata = jsonb_set(
    submissiondata::jsonb, 
    '{familyHOUSEHOLD,familyArray}',  -- ? Correct path to the array
    (
        SELECT jsonb_agg(
            CASE 
                WHEN elem->>'personid' = '36cabae9-d53a-40f5-a476-3066f21c435b'
                THEN jsonb_set(
                        jsonb_set(
                            jsonb_set(
                                elem, 
                                '{intakeservicerequestactorid}', 
                                '"ec94c2e8-84ec-455a-b690-5403cd80cb8c"', 
                                false
                            ),
                            '{personid}', 
                            '"f6102c9f-2031-4acb-b167-7a73f580529c"', 
                            false
                        ),
                        '{name}', 
                        '"ADONIS Hudson"', 
                        false
                    )
                ELSE elem
            END
        )
        FROM jsonb_array_elements(submissiondata::jsonb->'familyHOUSEHOLD'->'familyArray') AS elem
    ),
    true
)
WHERE servicecaseid = '106d52af-2455-478f-b3fb-97e6f8e94b7d'
  AND submissiondata::jsonb->'familyHOUSEHOLD'->'familyArray' @> 
      '[{"personid": "36cabae9-d53a-40f5-a476-3066f21c435b"}]'::jsonb
  AND assessmentid = 'fefb4fc4-9b6a-4551-bde5-b3bbf737f256'
  AND activeflag = 1;

