UPDATE assessment --needed as the dropdown values will be coming based on this
SET submissiondata = jsonb_set(
    submissiondata,
    '{all_childs_json}',
    '[{
      "age": "10 Yrs",
      "name": "AYDEN Hudson",
      "cjamspid": "200968973"
    },
    {
      "age": "6 Yrs",
      "cjamspid": "200971185",
      "name": "ADONIS Hudson"
    }
    ]'::jsonb  -- The new childArray as JSONB
)
WHERE submissiondata -> 'all_childs_json' IS NOT null
and assessmentid = '11b3b0db-be1f-4e66-9b25-81b5a822a9b7'
and activeflag=1;

update
	cjams.assessment
set
	submissiondata = jsonb_set(submissiondata, '{childdatagrid}', '[
    {
      "age": "6 Yrs",
      "clientid": "200971185",
      "childname": "ADONIS  Hudson"
    }
  ]') 
WHERE assessmentid = '11b3b0db-be1f-4e66-9b25-81b5a822a9b7'
and activeflag=1;

