    (
        SELECT jsonb_agg(
            CASE 
                WHEN elem->>'intakeservicerequestactorid' = '713641dd-5319-4d70-8122-02fc6b5f230f'
                     OR elem->>'intakeservicerequestactorid' = 'ff9999bf-4c3f-482d-81a8-ea2d4364a40e'
                THEN jsonb_set(
                        jsonb_set(
                            jsonb_set(
                                elem, 
                                '{intakeservicerequestactorid}', 
                                '"7f3621a9-a830-4f04-90c0-64d1a7751e46"', 
                                false
                            ),
                            '{participantid}', 
                            '"7f3621a9-a830-4f04-90c0-64d1a7751e46"', 
                            false
                        ),
                        '{lastname}', 
                        '"Hudson"', 
                        false
                    )
                ELSE elem
            END
        )
        FROM jsonb_array_elements(focusperson::jsonb->'focuspersonjson') AS elem
    )
)
WHERE servicecaseid = '106d52af-2455-478f-b3fb-97e6f8e94b7d'    
  AND activeflag = 1
  AND (
      focusperson::jsonb->'focuspersonjson' @> '[{"intakeservicerequestactorid": "713641dd-5319-4d70-8122-02fc6b5f230f"}]'::jsonb
      OR focusperson::jsonb->'focuspersonjson' @> '[{"intakeservicerequestactorid": "ff9999bf-4c3f-482d-81a8-ea2d4364a40e"}]'::jsonb
  );
